import json,pathlib,hashlib
root=pathlib.Path(__file__).resolve().parents[1]/'content/english-curriculum-repair/held-repairs'
old=json.loads((root/'source-questions.json').read_text());byindex={r['reviewIndex']:r for r in old}
passages={
 'smallpox':dict(title='A Long Campaign',text="In 1796, Edward Jenner tested whether material from cowpox could protect a person against smallpox. His work helped establish vaccination. Much later, the World Health Organization (WHO) led a worldwide effort against smallpox. WHO intensified its eradication programme in 1967. Teams used vaccination and surveillance: they protected people and looked for new cases. The last known naturally occurring case was recorded in Somalia in 1977. In 1980, WHO declared that smallpox had been eradicated. This means that the disease was no longer spreading naturally anywhere in the world. The result depended on coordinated work across countries, rather than on one scientist working alone.",sources=['https://www.who.int/health-topics/smallpox','https://www.who.int/news-room/spotlight/history-of-vaccination/history-of-smallpox-vaccination']),
 'colour':dict(title='More Than Three Colours',text="Light-sensitive cells called cones help eyes detect colour. Typical human colour vision uses three cone types, which are sensitive to different ranges of light wavelengths. These ranges are commonly associated with red, green and blue. The visual system compares the signals from the cone types; a cone is not simply a tiny pot of coloured paint. A system using three cone types is called trichromatic. A system using four is called tetrachromatic. Hummingbirds have four cone types. Experiments have shown that they can distinguish colour combinations that humans cannot normally tell apart. In this text, 'tetra' refers to four types of colour-sensitive cone, not four colours in the whole world.",sources=['https://www.nei.nih.gov/research-and-training/research-news/nei-scientists-use-retinal-connectomics-study-color-vision-circuitry-relevant-mood-myopia','https://www.princeton.edu/news/2020/06/15/wild-hummingbirds-see-broad-range-colors-humans-can-only-imagine','https://doi.org/10.1073/pnas.1919377117']),
 'flu':dict(title='Reading a Historical Estimate',text="A CDC history describes how the influenza pandemic spread worldwide during 1918-1919. It estimates that about 500 million people became infected, roughly one-third of the world's population at the time. The same account gives an estimate of at least 50 million deaths worldwide. These are historical estimates, rather than an exact count of every person. The passage identifies 1918-1919 as the period of worldwide spread. It does not give an exact percentage of the world's population who died.",sources=['https://archive.cdc.gov/www_cdc_gov/flu/pandemic-resources/1918-commemoration/1918-pandemic-history.htm']),
 'guide':dict(title='The Old Map',text="The guide pointed towards a narrow track and said that it would take us straight to the village. I nodded, but I did not put away my old map. At the first turning, I stopped to compare his directions with the lines on the paper. When he pointed left again, I checked the map a second time before following. The others were already chatting about lunch. I stayed quiet and kept the map open in my hands.",sources=[])
}
# Each entry is linked to a frozen source hash, but becomes a NEW question if released.
items=[
(6,'smallpox','Which organisation led the worldwide effort described in the passage?','The World Health Organization (WHO)',['A local school','One village council','A travel company'],'the World Health Organization (WHO) led a worldwide effort against smallpox'),
(18,'smallpox','According to the passage, in which year did Jenner test protection against smallpox?','1796',['1853','1967','1980'],'In 1796, Edward Jenner tested whether material from cowpox could protect a person against smallpox.'),
(54,'smallpox','What did Jenner test, according to the passage?','Whether material from cowpox could protect against smallpox',['Whether antibiotics could cure all diseases','Whether maps could identify new cases','Whether every disease disappeared in 1796'],'Edward Jenner tested whether material from cowpox could protect a person against smallpox.'),
(67,'smallpox','When did WHO intensify its eradication programme?','1967',['1796','1977','1980'],'WHO intensified its eradication programme in 1967.'),
(91,'smallpox','Where was the last known naturally occurring case recorded?','Somalia',['Britain','Canada','Japan'],'The last known naturally occurring case was recorded in Somalia in 1977.'),
(8,'colour','How many cone types do hummingbirds have, according to the passage?','Four',['Two','Three','Six'],'Hummingbirds have four cone types.'),
(9,'colour','The three human cone types are sensitive to different ranges of what?','Light wavelengths',['Sound frequencies','Air pressure','Body temperature'],'three cone types, which are sensitive to different ranges of light wavelengths'),
(29,'colour','Which colours are commonly associated with the three human cone ranges in the passage?','Red, green and blue',['Black, white and grey','Orange, purple and brown','Yellow, black and white'],'These ranges are commonly associated with red, green and blue.'),
(55,'colour','What does tetrachromatic mean in this passage?','Using four types of colour-sensitive cone',['Seeing exactly four colours','Having no cone cells','Using only red and green signals'],'A system using four is called tetrachromatic.'),
(95,'colour','What does trichromatic mean in this passage?','Using three cone types',['Seeing only three objects','Having three eyes','Using four cone types'],'A system using three cone types is called trichromatic.'),
(129,'flu','Which period does the passage identify for the pandemic’s worldwide spread?','1918-1919',['1796-1798','1853-1855','1967-1977'],'the influenza pandemic spread worldwide during 1918-1919'),
(44,'guide','Which detail best supports the inference that the narrator doubts the guide’s directions?','The narrator repeatedly checks the directions against an old map',['The guide points towards a narrow track','The others talk about lunch','The narrator is walking towards a village'],'When he pointed left again, I checked the map a second time before following.')
]
questions=[]
for i,(n,pid,stem,answer,wrong,evidence) in enumerate(items):
 source=byindex[n];passage=passages[pid];pos=i%4;opts=wrong.copy();opts.insert(pos,answer)
 inference=pid=='guide';focus=('eng.reading.inference.attitude-feeling.focus.select-evidence-that-establishes-narrator-distrust-130ba7e575' if inference else 'eng.reading.explicit-information.locate-detail.focus.esl-short-text-detail')
 tax=dict(primarySkillCode='eng.reading.inference' if inference else 'eng.reading.explicit-information',atomicSubskillCode='eng.reading.inference.attitude-feeling' if inference else 'eng.reading.explicit-information.locate-detail',evidenceFocusCode=focus,assessmentProcessCode='BH-AO3' if inference else 'BH-AO1',cognitiveProcess='analyze' if inference else 'understand',evidenceStatement='Selects an explicitly supplied action as evidence of narrator distrust.' if inference else 'Retrieves an explicitly stated detail from the self-contained passage.')
 questions.append(dict(externalId=f'english-reading-context-repair-20261026-{i+1:02}',sourceQuestionId=source['id'],sourceQuestionHash=source['current_content_hash'],topic='Reading: evidence for an inference' if inference else 'Reading: locating specific information',questionText=f"Read the passage.\n\n{passage['title']}\n{passage['text']}\n\n{stem}",questionType='multiple_choice',options=opts,correctAnswer=answer,explanation='The supplied passage supports this answer: '+evidence,difficulty='medium' if inference else 'easy',points=1,timeLimit=180,language='en',eligibleGrades=[g for g in source['eligible_grade_levels'] if g in (7,8)],hints=[],tags=['reading','self-contained passage','editorial repair candidate'],taxonomies=[tax],readingContext=dict(passageId=pid,passageText=passage['text'],stem=stem,evidenceQuote=evidence,questionMode='inference' if inference else 'explicit_retrieval',factualSources=passage['sources'])))
package=dict(schemaVersion=1,packageId='english-reading-context-repair-20261026',packageVersion='0.1.0-draft',contentVersion='english-reading-context-repair-v0.1',registryVersion='bh-english-core-v1',subjectCode='english',authority='Editorial candidate — not approved for publication',editorialReview=dict(status='draft',reviewedBy=None,approvedBy=None),releaseNotes='Twelve NEW, self-contained replacement candidates. Original IDs, hashes, attempts and historic results must remain unchanged. Dry-run validation is not content approval.',passages=passages,questions=questions)
(root/'reading-replacements.json').write_text(json.dumps(package,ensure_ascii=False,indent=2)+'\n')
# The present importer validates schema/taxonomy, not editorial-review declarations.
# Keep its call dry-run-only; never generate an activation command here.
(root/'validate-reading-replacements.sql').write_text("-- DRY RUN ONLY: no release or question records are written.\nselect public.rpc_import_registry_verified_mcq_package('"+json.dumps(package,ensure_ascii=False,separators=(',',':')).replace("'","''")+"'::jsonb,true);\n")
lines=['# Self-contained reading replacement candidates','', '**Status: editorial draft; not published.** Each candidate has a new external ID and references the old question’s exact content hash. Existing questions and student records are not overwritten.','', 'The factual passages are original paraphrases checked against the primary sources linked in the package. The narrative is original fiction. These candidates test supplied-text retrieval or inference; they do not require prior science or history knowledge.','', 'Three correct answers occupy each of A, B, C and D in this review ordering. The app may shuffle options.','']
for k,p in passages.items():
 lines += ['## '+p['title'],'',p['text'],'']
 if p['sources']:lines += ['Fact-check references: '+', '.join('['+str(i+1)+']('+u+')' for i,u in enumerate(p['sources']))+'.','']
 for q in questions:
  if q['readingContext']['passageId']!=k:continue
  lines += ['### '+q['externalId'],'',q['readingContext']['stem'],'']
  lines += [chr(65+j)+'. '+opt for j,opt in enumerate(q['options'])]
  lines += ['', '**Key: '+chr(65+q['options'].index(q['correctAnswer']))+' — '+q['correctAnswer']+'**','', 'Supporting text: '+q['readingContext']['evidenceQuote'],'']
(root/'READING_REPLACEMENTS.md').write_text('\n'.join(lines)+'\n')
print('Prepared',len(questions),'replacement candidates')
